-- Event-week task list (15–22.10), added to the existing tasks. Only on an
-- existing deployment (tasks already populated), so a fresh install still gets
-- the regular seed. Owners marked "לשיבוץ" are to be assigned in the UI.
INSERT INTO tasks (owner, title, status, due_date, notes)
SELECT v.owner, v.title, v.status, v.due_date, v.notes
  FROM (VALUES
  ($t$עודד טהורי + ערן רביב$t$, $t$החלטה: סרטון לכנס, כן או לא$t$, 'open', DATE '2026-10-16', $t$אם כן: סרטון פתיחה (עד 90 שניות) או סרטון סיכום? מי מצלם ביום האירוע? קובץ סופי עד 19.10.$t$),
  ($t$ערן רביב + מיטל נועם$t$, $t$החלטה: הגרלה, כן או לא$t$, 'open', DATE '2026-10-16', $t$ממשיך את המשימה ״סגירת הפרס ופורמט ההגרלה״. אם כן: הפרס, שיטת ההגרלה (פתקים / QR / מהרשימה) ומקום בלו״ז, שכרגע אין לה.$t$),
  ($t$מיטל נועם$t$, $t$סקר משוב בסוף האירוע$t$, 'open', DATE '2026-10-16', $t$3–5 שאלות לכל היותר. QR על המסך בדברי הסיום, וקישור במייל התודה למחרת.$t$),
  ($t$מתן ניצן$t$, $t$מפא״ת: לסגור בכתב מה מותר לצלם ולהקליט$t$, 'open', DATE '2026-10-16', $t$כולל הצגה כ״אל״ם ע׳״ בלבד. לעדכן את כרטיס המנחה בהתאם.$t$),
  ($t$לשיבוץ$t$, $t$איסוף מצגות סופיות מכל הדוברים$t$, 'open', DATE '2026-10-18', $t$עודד, מוטי, מירב, קובי, מפא״ת. לבדוק פונטים בעברית ותמונות על מחשב הבמה.$t$),
  ($t$מתן ניצן + ענבר הרבסט$t$, $t$הכנת ההדגמה החיה (10:10)$t$, 'open', DATE '2026-10-19', $t$תרחיש קבוע, נתוני דמו נקיים, משתמש מחובר מראש, סרטון גיבוי למקרה של תקלת רשת. חזרה עד 19.10.$t$),
  ($t$לשיבוץ$t$, $t$שקופיות מעבר: ברוכים הבאים, הפסקה, QR$t$, 'open', DATE '2026-10-18', $t$״ברוכים הבאים״, ״הפסקה, חוזרים ב-12:00״, ושקופית QR לסקר או להגרלה אם יוחלט.$t$),
  ($t$מתן ניצן + ערן רביב$t$, $t$השלמת כרטיסיות ההנחיה$t$, 'open', DATE '2026-10-18', $t$במסך ״כרטיסיות הנחיה״: למלא את השדות המסומנים ___ (Wi-Fi, שירותים, סקר) ולעבור על הנוסח.$t$),
  ($t$ערן רביב$t$, $t$שליחת השאלות מראש לחברי הפאנל$t$, 'open', DATE '2026-10-16', $t$לכל אחד: השאלה האישית שלו והשאלה המשותפת לכולם.$t$),
  ($t$ערן רביב$t$, $t$אישור סופי של הגעת ששת חברי הפאנל$t$, 'open', DATE '2026-10-18', $t$אם מישהו מבטל, לקבוע מחליף.$t$),
  ($t$לשיבוץ$t$, $t$סדר ישיבה ושלטי שם לפאנל$t$, 'open', DATE '2026-10-19', $t$7 כיסאות על הבמה (6 משתתפים ומנחה).$t$),
  ($t$ערן רביב$t$, $t$שליחת תזכורת למאושרים ו-last call$t$, 'open', DATE '2026-10-16', $t$node scripts/send-reminder.js ואחריו --audience=last-call.$t$),
  ($t$לשיבוץ$t$, $t$מעקב יומי אחרי תשובות לתזכורת$t$, 'open', DATE '2026-10-19', $t$ווידג׳ט ״אימות הגעה״: ביטולים ו״עוד לא בטוחים״. מקומות שהתפנו מציעים לרשימת ההמתנה.$t$),
  ($t$לשיבוץ$t$, $t$שיחות למי שלא השיב לתזכורת$t$, 'open', DATE '2026-10-19', $t$בוט או ידנית.$t$),
  ($t$לשיבוץ$t$, $t$רשימת משתתפים סופית$t$, 'open', DATE '2026-10-19', $t$לעמדת הקבלה (מודפסת, לפי א״ב) ולכיבוד.$t$),
  ($t$לשיבוץ$t$, $t$אישורי כניסה לבניין (מגדלי עזריאלי שרונה)$t$, 'open', DATE '2026-10-18', $t$לבדוק מול האבטחה מתי הם צריכים את רשימת האורחים.$t$),
  ($t$מיטל נועם + יעל$t$, $t$כיבוד: כמות סופית$t$, 'open', DATE '2026-10-19', $t$לפי הרשימה הסופית. כשרות ואפשרויות צמחוניות.$t$),
  ($t$לשיבוץ$t$, $t$עמדת קבלה ותגי שם$t$, 'open', DATE '2026-10-19', $t$רשימה מודפסת, תגי שם, שני אנשים בעמדה מ-09:00.$t$),
  ($t$לשיבוץ$t$, $t$סידור האולם$t$, 'open', DATE '2026-10-19', $t$כיסאות לפי מספר המאושרים ועוד 10%, במה, שולחן כיבוד.$t$),
  ($t$לשיבוץ$t$, $t$הנחיות הגעה למשתתפים$t$, 'open', DATE '2026-10-19', $t$חניה, כניסה, קומה 34. הודעה ב-19.10.$t$),
  ($t$לשיבוץ$t$, $t$חזרה גנרלית טכנית$t$, 'open', DATE '2026-10-19', $t$מחשב במה, מסך, קליקר, גיבוי מצגות ב-USB, מיקרופונים (2 לבמה, 1 נייד לקהל, לפאנל), Wi-Fi (רשת נפרדת להדגמה), טיימר לדוברים.$t$),
  ($t$לשיבוץ$t$, $t$יום האירוע: הקמה ובדיקות$t$, 'open', DATE '2026-10-20', $t$07:45–08:30: הקמה, בדיקת סאונד, מצגות ומחשב הדמו. 09:00 עמדת קבלה פתוחה.$t$),
  ($t$לשיבוץ$t$, $t$יום האירוע: אחראי זמנים$t$, 'open', DATE '2026-10-20', $t$מסמן לדוברים כשנותרו 5 ו-2 דקות.$t$),
  ($t$לשיבוץ$t$, $t$יום האירוע: צילום לרשתות$t$, 'open', DATE '2026-10-20', $t$לפי מה שסוכם עם מפא״ת.$t$),
  ($t$לשיבוץ$t$, $t$מייל תודה לאחר האירוע$t$, 'open', DATE '2026-10-21', $t$קישור לסקר, מצגות (באישור הדוברים) ותמונות.$t$),
  ($t$לשיבוץ$t$, $t$פוסט LinkedIn על האירוע$t$, 'open', DATE '2026-10-21', NULL),
  ($t$לשיבוץ$t$, $t$מעקב לידים אחרי האירוע$t$, 'open', DATE '2026-10-22', $t$מי שאל בפאנל, ומי ביקש הדגמה.$t$)
  ) AS v(owner, title, status, due_date, notes)
 WHERE EXISTS (SELECT 1 FROM tasks);
